  "quiz": [
    {
      "id": "q1",
      "q": "北塔禁室里那口钉着白玫瑰徽章的木箱，对应的是谁？",
      "options": [
        {
          "key": "A",
          "text": "第一位王后戚白玫"
        },
        {
          "key": "B",
          "text": "第二位王后欧夜莺"
        },
        {
          "key": "C",
          "text": "王后鬼镜心"
        },
        {
          "key": "D",
          "text": "侍童撒小木"
        }
      ],
      "answer": "A",
      "clue": "jj_north_2",
      "explain": "白玫瑰徽章对应第一位王后戚白玫：戚纺纱床下小像的背面题着「吾女白玫，殁于北塔」，钟楼底本也记着她被送进北塔、一月后抬出。"
    },
    {
      "id": "q2",
      "q": "十五年前，国王手令里要张不射带进黑森林的「那孩子」是谁？",
      "options": [
        {
          "key": "A",
          "text": "公主甄蔷薇"
        },
        {
          "key": "B",
          "text": "侍童撒小木"
        },
        {
          "key": "C",
          "text": "二王后欧夜莺的女儿小莺"
        },
        {
          "key": "D",
          "text": "猎户自己的女儿"
        }
      ],
      "answer": "C",
      "clue": "jj_wei_3",
      "explain": "钟楼底本记着二王后之女小莺由猎户夜里抱出南门；夜莺徽章木箱里的手令写着带进黑森林、取心回来。"
    },
    {
      "id": "q3",
      "q": "纺纱婆戚纺纱和公主甄蔷薇是什么关系？",
      "options": [
        {
          "key": "A",
          "text": "毫无血缘的乳娘"
        },
        {
          "key": "B",
          "text": "姑母与侄女"
        },
        {
          "key": "C",
          "text": "师父与徒弟"
        },
        {
          "key": "D",
          "text": "外祖母与外孙女"
        }
      ],
      "answer": "D",
      "clue": "jj_qi_4",
      "explain": "戚纺纱的小像画着戴白玫瑰花冠的女儿抱着金发婴儿，公主首饰盒里的白玫瑰银坠背面是「白玫」两字：公主是戚白玫的女儿，戚纺纱的外孙女。"
    },
    {
      "id": "q4",
      "q": "侍童撒小木当年被投入荆棘丛，罪名是什么？",
      "options": [
        {
          "key": "A",
          "text": "偷了北塔的金钥匙"
        },
        {
          "key": "B",
          "text": "打碎了公主的八音盒"
        },
        {
          "key": "C",
          "text": "撒谎说公主中了诅咒"
        },
        {
          "key": "D",
          "text": "私放了北塔里的人"
        }
      ],
      "answer": "A",
      "clue": "jj_wei_3",
      "explain": "底本记着撒小木被指偷了北塔金钥匙，投荆棘丛，第二天钥匙在国王自己的靴子里找到。"
    },
    {
      "id": "q5",
      "q": "第二位王后欧夜莺进荆棘堡之前，是做什么的？",
      "options": [
        {
          "key": "A",
          "text": "镜坊的女儿"
        },
        {
          "key": "B",
          "text": "河镇歌馆的歌女"
        },
        {
          "key": "C",
          "text": "纺锤阁的学徒"
        },
        {
          "key": "D",
          "text": "邻国的公主"
        }
      ],
      "answer": "B",
      "clue": "jj_ou_3",
      "explain": "欧灰灰枕下那首《夜莺》摇篮曲的纸背面写着河镇歌馆、欧夜莺；底本也记着她是河镇歌女。"
    },
    {
      "id": "q6",
      "q": "王后鬼镜心带进宫的那面大银镜，出自哪里？",
      "options": [
        {
          "key": "A",
          "text": "黑沼公爵的赏赐"
        },
        {
          "key": "B",
          "text": "河镇的吹玻璃匠"
        },
        {
          "key": "C",
          "text": "鬼家镜坊"
        },
        {
          "key": "D",
          "text": "国王的库房"
        }
      ],
      "answer": "C",
      "clue": "jj_gui_1",
      "explain": "银镜的镜框背面烙着「鬼家镜坊」，那是王后娘家的镜坊。"
    }
  ],
